export const title = "How to Choose an L-Shaped Desk for a Small Room";
export const metaTitle = "How to Choose an L-Shaped Desk for a Small Room";
export const metaDescription = "Choose the seated position and return direction on a measured room plan before comparing desk models. Check both outer dimensions, the depth of each.";
export const author = "Jamie Cole, Lead Product Researcher";
export const datePublished = "2026-11-10";
